const $=id=>document.getElementById(id);
let lesson=lessons[lessons.length-1];
const storeGet=(key)=>{try{return localStorage.getItem(key)}catch{return null}};
const storeSet=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
let level=Number(storeGet('dayun:level')||1);
if(![1,2,3].includes(level))level=1;
let tab='train',trainPage=0,sentencePage=0,wordPage=0,qIndex=0,qScore=0,qLocked=false,quizDone=false;
let scoreById={},audioCtx=null,toastTimer=0;
const stateKey=()=>`dayun:${lesson.id}`;
try{scoreById=JSON.parse(storeGet(stateKey())||'{}')||{}}catch{scoreById={}}
let soundOn=storeGet('dayun:sounds')!=='off';
const available=()=>lesson.forms; // All seven forms remain visible at every level
const save=()=>{try{storeSet(stateKey(),JSON.stringify(scoreById))}catch{toast('이 브라우저에서는 기록 저장이 제한돼요')}};
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function makeAudio(){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;try{audioCtx??=new C();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}catch{return null}}
function tone(freq=500,dur=.12,type='sine',vol=.08,delay=0){if(!soundOn)return;const c=makeAudio();if(!c)return;const at=c.currentTime+delay;const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,at);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(Math.max(.002,vol),at+.012);g.gain.exponentialRampToValueAtTime(.0001,at+dur);o.connect(g).connect(c.destination);o.start(at);o.stop(at+dur+.01)}
function playFx(which){if(!soundOn)return;if(which==='tap'){tone(680,.07,'sine',.035)}else if(which==='correct'){tone(659,.14,'sine',.075);tone(784,.15,'sine',.075,.12);tone(988,.24,'sine',.085,.25);applause()}else if(which==='wrong'){tone(214,.19,'triangle',.06);tone(174,.19,'triangle',.04,.12)}else if(which==='success'){tone(523,.12,'sine',.08);tone(659,.12,'sine',.08,.1);tone(784,.12,'sine',.08,.2);tone(1046,.35,'sine',.1,.32);applause(.38)}}
// A brief, soft applause effect synthesized from locally generated noise. No copyrighted sound files.
function applause(offset=.17){const c=makeAudio();if(!c||!soundOn)return;const buffer=c.createBuffer(1,Math.round(c.sampleRate*.075),c.sampleRate);const d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,1.2);for(let i=0;i<8;i++){const src=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain(),t=c.currentTime+offset+i*.065;src.buffer=buffer;filter.type='highpass';filter.frequency.value=950;gain.gain.setValueAtTime(.001,t);gain.gain.linearRampToValueAtTime(.033,t+.009);gain.gain.exponentialRampToValueAtTime(.0001,t+.07);src.connect(filter).connect(gain).connect(c.destination);src.start(t);src.stop(t+.075)}}
function say(text){if(!('speechSynthesis' in window)){toast('음성 기능이 없는 브라우저예요');return;}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.rate=.83;u.pitch=1;const vs=speechSynthesis.getVoices();const ja=vs.find(x=>x.lang?.toLowerCase().startsWith('ja'));if(ja)u.voice=ja;u.onerror=()=>toast('일본어 음성을 재생하지 못했어요. 휴대폰의 TTS 설정을 확인해 주세요.');speechSynthesis.speak(u)}catch{toast('일본어 음성 재생을 확인해 주세요')}}
function burst(n=19){const layer=$('fx-layer');layer.replaceChildren();const colors=['#ff99b6','#ffd565','#82d6f6','#8c7af1','#78e1bc'];for(let i=0;i<n;i++){const el=document.createElement('span');el.className='confetti';el.style.background=colors[i%colors.length];el.style.setProperty('--dx',`${(Math.random()-.5)*320}px`);el.style.setProperty('--dy',`${-70+Math.random()*190}px`);el.style.setProperty('--r',`${(Math.random()-.5)*800}deg`);layer.append(el)}setTimeout(()=>layer.replaceChildren(),950)}
const escapeHtml=str=>String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const speaker=(what,idx,label='발음 듣기')=>`<button type="button" class="speak-circle" data-speak="${what}" data-index="${idx}" aria-label="${label}">▶</button>`;
function render(){const forms=available(),footer=$('footer-status');$('app').classList.toggle('train-screen',tab==='train');$('day-label').textContent=`DAY ${String(lesson.day).padStart(2,'0')} ▾`; $('hero-word').textContent=lesson.kanji;$('hero-kana').textContent=lesson.reading;$('hero-ko').textContent=lesson.title;$('level-open').innerHTML=`LV.${level} <span aria-hidden="true">⌄</span>`;
 document.querySelectorAll('[data-tab]').forEach(b=>{let v=b.dataset.tab===tab;b.classList.toggle('active',v);b.setAttribute('aria-selected',String(v))});
 if(tab==='train'){footer.textContent=`LEVEL ${level} · ${forms.length}가지 변화형 익히기`;renderTrain(forms)}
 if(tab==='sentence'){footer.textContent=`일본어 → 히라가나 → 해석`;renderSentence(forms)}
 if(tab==='word'){footer.textContent='예문에 나온 단어를 외워요';renderWords()}
 if(tab==='quiz'){footer.textContent='맞히면 점수와 박수 효과!';renderQuiz(forms)}
}
function trainCard(f,i){return `<article class="study-row"><span class="row-label">${escapeHtml(f.name)}</span><span class="row-jp" lang="ja">${escapeHtml(f.kanji)}</span><span class="row-ko">${escapeHtml(f.ko)}</span><button type="button" class="row-speak" data-speak="train" data-index="${i}" aria-label="${escapeHtml(f.name)} 일본어 발음 듣기"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 9a5 5 0 0 1 0 6M18 6a9 9 0 0 1 0 12"/></svg></button></article>`}
function pageNav(current,total,which){if(total<=1)return `<div class="train-caption"><b>오늘의 목표</b> 일본어를 듣고 소리 내어 따라 말하기</div>`;return `<div class="view-nav"><button class="round-nav" type="button" data-nav="${which}-prev" ${current===0?'disabled':''} aria-label="이전 카드">‹</button><span class="page-counter">${current+1} / ${total}</span><button class="round-nav" type="button" data-nav="${which}-next" ${current===total-1?'disabled':''} aria-label="다음 카드">›</button></div>`}
function renderTrain(forms){trainPage=0;$('workspace').innerHTML=`<section class="view train-one-line"><div class="section-head"><h2>동사 변신 7가지</h2><span class="tiny-label">듣고 따라 말해요</span></div><div class="form-rows">${forms.map((f,i)=>trainCard(f,i)).join('')}</div></section>`}
function renderSentence(forms){sentencePage=Math.min(sentencePage,forms.length-1);const f=forms[sentencePage];const sentence=escapeHtml(f.prefix)+`<mark>${escapeHtml(f.kanji)}</mark>`+escapeHtml(f.suffix);$('workspace').innerHTML=`<section class="view"><div class="section-head"><h2>문장으로 말해봐</h2><small>${sentencePage+1} / ${forms.length}</small></div><article class="sentence-box"><div class="sentence-top"><span class="sentence-badge">${escapeHtml(f.name)}</span><span class="quiz-count">문장 ${sentencePage+1}</span></div><div class="sentence-graphic"><img src="${escapeHtml(lesson.fallback)}" alt="학교로 가는 아이"/><div>들으면서<br>따라 말하기</div></div><div class="sentence-text" lang="ja">${sentence}</div><div><div class="reading-label">히라가나 읽기</div><div class="sentence-kana" lang="ja">${escapeHtml(f.kana)}</div></div><div><div class="reading-label">한국어 뜻</div><div class="sentence-translation">${escapeHtml(f.meaning)}</div></div><button class="sentence-speak" data-speak="sentence" data-index="${sentencePage}" type="button">▶ 일본어 문장 듣기</button></article>${pageNav(sentencePage,forms.length,'sentence')}</section>`}
function wordSVG(type){const attrs='fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"';const shapes={school:'<path d="M4 28V12l12-7 12 7v16M9 12h14M9 18h3m8 0h3M13 28v-7h6v7"/>',sun:'<circle cx="16" cy="16" r="6"/><path d="M16 2v4M16 26v4M2 16h4m20 0h4M6 6l3 3m14 14 3 3M6 26l3-3M23 9l3-3"/>',calendar:'<rect x="4" y="7" width="24" height="21" rx="3"/><path d="M4 13h24M10 3v8m12-8v8M10 19h4m-4 4h10"/>',tree:'<path d="M16 20v10M8 20c-5 0-5-8 0-9 0-8 12-10 15-4 8 0 9 12 1 13H8Z"/>',cloud:'<path d="M8 24c-8 0-8-12 0-12 3-11 17-10 20 1 7 1 7 11 0 11H8Z"/>',book:'<path d="M16 8c-4-4-8-4-12-2v21c5-2 8-1 12 2 4-3 7-4 12-2V6c-4-2-8-2-12 2v21"/>',repeat:'<path d="M5 12a12 12 0 0 1 22-2l-1-6m1 6h-7M27 20a12 12 0 0 1-22 2l1 6m-1-6h7"/>'};return `<svg viewBox="0 0 32 32" aria-hidden="true" ${attrs}>${shapes[type]||shapes.book}</svg>`}
function renderWords(){const words=lesson.words;const pages=Math.ceil(words.length/4);wordPage=Math.min(wordPage,pages-1);const from=wordPage*4;const a=words.slice(from,from+4);$('workspace').innerHTML=`<section class="view"><div class="section-head"><h2>문장 속 단어 찾기</h2><span class="tiny-label">${words.length}개 단어</span></div><div class="word-grid">${a.map((w,i)=>`<article class="vocab-card"><div class="vocab-visual">${wordSVG(w.visual)}</div>${speaker('word',from+i,w.kana+' 발음 듣기')}<div class="vocab-jp" lang="ja">${escapeHtml(w.jp)}</div><div class="vocab-kana" lang="ja">${escapeHtml(w.kana)}</div><div class="vocab-meaning">${escapeHtml(w.ko)}</div></article>`).join('')}</div>${pageNav(wordPage,pages,'word')}</section>`}
// Stable distractors: each question always has exactly one correct option.
function quizOptions(index,forms){const correct=forms[index],others=forms.filter(x=>x.id!==correct.id);const selected=others.slice(0,3);if(selected.length<3)throw Error('Need at least four forms');const set=[...selected,correct];return set.sort((a,b)=>((a.id.charCodeAt(0)+index*7)%11)-((b.id.charCodeAt(0)+index*7)%11));}
function quizQuestion(f,forms){const opts=quizOptions(qIndex,forms);return `<section class="view"><div class="quiz-top"><span class="quiz-count">문제 ${qIndex+1} / ${forms.length}</span><span class="quiz-score">★ ${Math.round(qScore/forms.length*100)}점</span></div><div class="progress-track"><div class="progress-fill" style="width:${qIndex/forms.length*100}%"></div></div><article class="quiz-question"><div class="quiz-help">빈칸에 들어갈 표현을 골라봐!</div><div class="quiz-jp" lang="ja">${escapeHtml(f.prefix)} <span class="blank"></span>${escapeHtml(f.suffix)}</div><div class="quiz-kana" lang="ja">${escapeHtml(f.kanaPrefix)} ____ ${escapeHtml(f.kanaSuffix)}</div><div class="quiz-ko">${escapeHtml(f.quizKo)}</div></article><div class="option-grid">${opts.map(o=>`<button type="button" class="option" data-answer="${escapeHtml(o.id)}" lang="ja">${escapeHtml(o.jp)}</button>`).join('')}</div><div class="quiz-feedback"><span class="feedback-text" id="quiz-feedback">정답을 골라 보세요</span><button type="button" class="next-button" id="quiz-next" hidden>다음 →</button></div></section>`}
function renderQuiz(forms){if(quizDone){const percent=Math.round(qScore/forms.length*100);const success=percent>=75;$('workspace').innerHTML=`<section class="view"><div class="section-head"><h2>오늘의 결과</h2><span class="tiny-label">${forms.length}문제 완료</span></div><div class="result"><div class="result-visual stamp">${success?'🏆':'🌱'}</div><div class="result-title">${success?'대단해, 다윤아!':'조금 더 해볼까?'}</div><div class="result-score">${percent}점</div><div class="result-sub">${forms.length}문제 중 ${qScore}문제 정답<br>${success?'밤에 아빠에게 한 문장 말해 보자!':'다시 도전하면 더 잘할 수 있어!'}</div><button type="button" data-action="retry">다시 도전하기</button><button type="button" data-action="parent" class="secondary">밤에 아빠와 확인하기</button></div></section>`;return;}qIndex=Math.min(qIndex,forms.length-1);$('workspace').innerHTML=quizQuestion(forms[qIndex],forms)}
function answerQuiz(id){if(qLocked||quizDone)return;const forms=available(),f=forms[qIndex],correct=id===f.id;qLocked=true;if(correct){qScore++;playFx('correct');burst(22)}else playFx('wrong');const buttons=[...$('workspace').querySelectorAll('[data-answer]')];for(const b of buttons){b.disabled=true;if(b.dataset.answer===f.id)b.classList.add('correct');else if(b.dataset.answer===id)b.classList.add('wrong')}const fb=$('quiz-feedback');fb.textContent=correct?'정답! 잘했어!':'아쉽다! 정답은 '+f.jp+' 이야.';$('quiz-next').hidden=false;$('quiz-next').textContent=qIndex===forms.length-1?'결과 보기':'다음 문제 →'}
function nextQuiz(){const forms=available();qIndex++;qLocked=false;if(qIndex>=forms.length){quizDone=true;scoreById.best=Math.max(scoreById.best||0,Math.round(qScore/forms.length*100));scoreById.last=Math.round(qScore/forms.length*100);save();playFx('success');burst(35)}render()}
function resetQuiz(){qIndex=0;qScore=0;qLocked=false;quizDone=false;render()}
function setTab(v){tab=v;playFx('tap');render()}
function openParent(){const questions=lesson.parentQuestions;$('parent-questions').innerHTML=questions.map((q,i)=>`<label><input type="checkbox" data-parent="${i}"><span>${escapeHtml(q)}</span></label>`).join('');$('dad-complete').disabled=true;$('dad-dialog').showModal()}
$('workspace').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.speak){const i=Number(b.dataset.index);if(b.dataset.speak==='train')say(available()[i].jp);else if(b.dataset.speak==='sentence')say(available()[i].kana);else if(b.dataset.speak==='word')say(lesson.words[i].kana);return}if(b.dataset.answer){answerQuiz(b.dataset.answer);return}if(b.id==='quiz-next'){nextQuiz();return}if(b.dataset.action==='retry'){resetQuiz();return}if(b.dataset.action==='parent'){openParent();return}if(b.dataset.nav){const [mode,dir]=b.dataset.nav.split('-');if(mode==='train')trainPage+=dir==='next'?1:-1;if(mode==='sentence')sentencePage+=dir==='next'?1:-1;if(mode==='word')wordPage+=dir==='next'?1:-1;playFx('tap');render()}});
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
$('hero-speak').addEventListener('click',()=>say(lesson.reading));
$('day-label').addEventListener('click',()=>{
 $('day-options').innerHTML=lessons.map((l,i)=>`<button type="button" data-day="${i}" class="${l.id===lesson.id?'active':''}"><b>DAY ${String(l.day).padStart(2,'0')} · ${escapeHtml(l.kanji)} (${escapeHtml(l.reading)})</b><span>${escapeHtml(l.title)} · ${escapeHtml(l.note)}</span></button>`).join('');
 $('day-dialog').showModal();
});
$('day-options').addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(!b)return;lesson=lessons[Number(b.dataset.day)];try{scoreById=JSON.parse(storeGet(stateKey())||'{}')||{}}catch{scoreById={}};tab='train';trainPage=0;sentencePage=0;wordPage=0;resetQuiz();$('day-dialog').close();const image=$('hero-image');const next=new Image();next.onload=()=>image.src=lesson.image;next.onerror=()=>image.src=lesson.fallback;next.src=lesson.image;});
$('level-open').addEventListener('click',()=>{document.querySelectorAll('[data-level]').forEach(b=>b.classList.toggle('active',Number(b.dataset.level)===level));$('level-dialog').showModal()});
document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>{level=Number(b.dataset.level);storeSet('dayun:level',String(level));trainPage=0;sentencePage=0;qIndex=0;qScore=0;qLocked=false;quizDone=false;$('level-dialog').close();toast(`LEVEL ${level}로 변경했어요`);render()}));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
$('dad-open').addEventListener('click',openParent);
$('parent-questions').addEventListener('change',()=>{$('dad-complete').disabled=[...$('parent-questions').querySelectorAll('input')].some(i=>!i.checked)});
$('dad-complete').addEventListener('click',()=>{scoreById.dadApproved=true;scoreById.approvedAt=new Date().toISOString();save();$('dad-dialog').close();playFx('success');burst(35);toast('아빠 확인 완료! 오늘도 잘했어!');$('footer-status').textContent='오늘의 아빠 확인 도장 완료!'});
$('sound-toggle').addEventListener('click',()=>{soundOn=!soundOn;storeSet('dayun:sounds',soundOn?'on':'off');$('sound-toggle').setAttribute('aria-pressed',String(soundOn));$('sound-toggle').setAttribute('aria-label',soundOn?'효과음 끄기':'효과음 켜기');$('sound-icon').textContent=soundOn?'♫':'♪';if(soundOn)playFx('tap');toast(soundOn?'효과음을 켰어요':'효과음을 껐어요')});
